<!-- User registration page. -->
<script setup lang="ts">import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; const auth = useAuthStore(); const router = useRouter(); const email = ref(''); const password = ref(''); const displayName = ref(''); const submit = async (): Promise<void> => { if (await auth.register(email.value, password.value, displayName.value)) await router.push('/categories'); };</script>
<template><main class="mx-auto max-w-md p-5 md:pt-16"><h1 class="text-2xl font-semibold">注册 AlgoLift</h1><form class="mt-6 space-y-4" @submit.prevent="submit"><label class="block text-sm">邮箱<input v-model="email" type="email" required aria-label="邮箱" class="mt-1 w-full border bg-transparent p-2" /></label><label class="block text-sm">密码<input v-model="password" type="password" required aria-label="密码" class="mt-1 w-full border bg-transparent p-2" /></label><label class="block text-sm">显示名称<input v-model="displayName" type="text" aria-label="显示名称" class="mt-1 w-full border bg-transparent p-2" /></label><p v-if="auth.registerError" role="alert" class="text-red-700">{{ auth.registerError }}</p><button :disabled="auth.loading" class="w-full bg-[var(--color-accent)] px-4 py-2 text-white">{{ auth.loading ? '注册中…' : '注册' }}</button></form><RouterLink class="mt-5 inline-block underline" to="/login">已有账号？登录</RouterLink></main></template>
